contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Acts as the LRTConfig: every call into it (e.g. hasRole) returns true.
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }

    receive() external payable {}

    function run(uint256 maxCount, address ndc) public {
        require(ndc != address(0));
        require(maxCount < type(uint256).max - 1);

        // initialize with this contract as lrtConfig (all lookups succeed via fallback)
        c.initialize(address(this));
        c.updateMaxNodeDelegatorCount(maxCount);

        address[] memory arr = new address[](1);
        arr[0] = ndc;

        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(arr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;
        if (reverted) {
            assert(beforeLen + 1 > maxCount && afterLen == beforeLen);
        } else {
            assert(beforeLen + 1 <= maxCount && afterLen == beforeLen + 1);
        }
    }
}

contract InvMutTest {
    C c;
