    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }

    receive() external payable {}

    function run(uint256 dummy) public {
        require(dummy < type(uint256).max);

        // initialize with this contract as lrtConfig (all role checks succeed via fallback)
        c.initialize(address(this));

        // first pause succeeds (manager role granted via fallback)
        c.pause();

        // second pause must revert because already paused
        bool reverted;
        try c.pause() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // still paused
        bool pausedAfterSecondPause = c.paused();

        // unpause succeeds (admin role via fallback) and clears the flag
        c.unpause();
        bool pausedAfterUnpause = c.paused();

        assert(reverted && pausedAfterSecondPause && !pausedAfterUnpause);
    }
}

