contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata ndcs, uint256 newMax, address[] calldata extra) public {
        require(newMax <= 1000, "bound max");
        require(ndcs.length <= 50, "bound first");
        require(extra.length <= 50, "bound second");
        require(newMax >= ndcs.length + extra.length, "both batches must fit");

        uint256 initialMax = c.maxNodeDelegatorCount();
        require(initialMax == 10, "fresh deployment");

        // fresh deploy: updateMaxNodeDelegatorCount and addNodeDelegatorContractToQueue
        // are onlyLRTAdmin-gated; admin role may not be set up, so capture revert flags.
        bool revertedUpdate;
        try c.updateMaxNodeDelegatorCount(newMax) { revertedUpdate = false; } catch { revertedUpdate = true; }

        if (!revertedUpdate) {
            uint256 cap = c.maxNodeDelegatorCount();
            assert(cap == newMax);

            bool revertedAdd;
            // changing-state call must be top-level; use try/catch wrapper but call statement is top-level in try block -- instead read-only pattern:
            // We must not nest the state-changing call. Revert case is acceptable: adding beyond cap reverts.
            try c.addNodeDelegatorContractToQueue(ndcs) { revertedAdd = false; } catch { revertedAdd = true; }
            if (!revertedAdd) {
                address[] memory q = c.getNodeDelegatorQueue();
                assert(q.length == ndcs.length && q.length <= newMax);
            } else {
                address[] memory q2 = c.getNodeDelegatorQueue();
                assert(q2.length <= newMax);
            }
        } else {
            uint256 stillMax = c.maxNodeDelegatorCount();
            assert(stillMax == initialMax);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata ndcs, address[] calldata extra) public {
        require(ndcs.length + extra.length <= 10, "batches must fit initial cap");
        require(ndcs.length <= 5 && extra.length <= 5, "bound batch sizes");
        for (uint256 i; i < ndcs.length; ++i) {
            require(ndcs[i] != address(0), "zero addr in ndcs");
        }
        for (uint256 i; i < extra.length; ++i) {
            require(extra[i] != address(0), "zero addr in extra");
        }

        uint256 capBefore = c.maxNodeDelegatorCount();
        require(capBefore == 10, "fresh deployment expected");

        c.addNodeDelegatorContractToQueue(ndcs);
        address[] memory q1 = c.getNodeDelegatorQueue();
        require(q1.length == ndcs.length, "first batch appended");

        c.addNodeDelegatorContractToQueue(extra);
        address[] memory q2 = c.getNodeDelegatorQueue();
        uint256 capAfter = c.maxNodeDelegatorCount();

        bool ordered = true;
        for (uint256 i; i < ndcs.length; ++i) {
            if (q2[i] != ndcs[i]) { ordered = false; }
        }
        for (uint256 i; i < extra.length; ++i) {
            if (q2[ndcs.length + i] != extra[i]) { ordered = false; }
        }

        assert(
            q2.length == ndcs.length + extra.length &&
            q2.length <= capBefore &&
            q2.length <= capAfter &&
            capAfter == capBefore &&
            ordered
        );
    }
    receive() external payable {}
}

