contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address cfgAddr, address asset, address ndc, uint256 newCount) public payable {
        // 1) initialize must ALWAYS revert (constructor disabled initializers)
        bool initReverted;
        try c.initialize(cfgAddr) { initReverted = false; } catch { initReverted = true; }

        // 2) privileged calls from a non-admin/non-manager caller must always revert
        bool pauseReverted;
        try c.pause() { pauseReverted = false; } catch { pauseReverted = true; }

        bool unpauseReverted;
        try c.unpause() { unpauseReverted = false; } catch { unpauseReverted = true; }

        address[] memory ndcs = new address[](1);
        ndcs[0] = ndc;
        bool addReverted;
        try c.addNodeDelegatorContractToQueue(ndcs) { addReverted = false; } catch { addReverted = true; }

        bool updReverted;
        try c.updateMaxNodeDelegatorCount(newCount) { updReverted = false; } catch { updReverted = true; }

        bool updCfgReverted;
        try c.updateLRTConfig(cfgAddr) { updCfgReverted = false; } catch { updCfgReverted = true; }

        // 3) state is unchanged by all these failed calls
        uint256 maxNdcAfter = c.maxNodeDelegatorCount();
        bool pausedAfter = c.paused();
        address lrtConfigAfter = c.lrtConfig();
        address[] memory queueAfter = c.getNodeDelegatorQueue();

        assert(
            initReverted &&
            pauseReverted &&
            unpauseReverted &&
            addReverted &&
            updReverted &&
            updCfgReverted &&
            maxNdcAfter == 0 &&
            pausedAfter == false &&
            lrtConfigAfter == address(0) &&
            queueAfter.length == 0
        );
    }

    receive() external payable {}
}

